calculationScript:
const r = tables[0].rows[0];
const t = parseFloat(r[1]);
const period = t / 10;
return { period: period.toFixed(2) };

simulationScript:
ctx.clearRect(0, 0, width, height);
ctx.beginPath();
ctx.moveTo(width / 2, 0);
const angle = Math.sin(frame * 0.05) * 0.2;
const length = params.length * 100;
const bobX = width / 2 + length * Math.sin(angle);
const bobY = length * Math.cos(angle);
ctx.lineTo(bobX, bobY);
ctx.stroke();
ctx.beginPath();
ctx.arc(bobX, bobY, 15, 0, 2 * Math.PI);
ctx.fillStyle = 'red';
ctx.fill();
